import re


class StackUnderflowError(Exception):
    pass


_NUMBER_RE = re.compile(r"^-?\d+$")


def _underflow():
    raise StackUnderflowError("Insufficient number of items in stack")


def _pop_one(stack):
    if not stack:
        _underflow()
    return stack.pop()


def _pop_two(stack):
    if len(stack) < 2:
        _underflow()
    b = stack.pop()
    a = stack.pop()
    return a, b


def _add(stack):
    a, b = _pop_two(stack)
    stack.append(a + b)


def _sub(stack):
    a, b = _pop_two(stack)
    stack.append(a - b)


def _mul(stack):
    a, b = _pop_two(stack)
    stack.append(a * b)


def _div(stack):
    a, b = _pop_two(stack)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    stack.append(a // b)


def _dup(stack):
    stack.append(_pop_one(stack))


def _drop(stack):
    _pop_one(stack)


def _swap(stack):
    a, b = _pop_two(stack)
    stack.extend((b, a))


def _over(stack):
    if len(stack) < 2:
        _underflow()
    stack.append(stack[-2])


BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _parse_token(token):
    token = token.lower()
    if _NUMBER_RE.match(token):
        return int(token)
    return token


def _dispatch(token, stack, words):
    if isinstance(token, int):
        stack.append(token)
    elif token in words:
        _execute(words[token], stack, words)
    elif token in BUILTINS:
        BUILTINS[token](stack)
    else:
        raise ValueError("undefined operation")


def _execute(tokens, stack, words):
    for token in tokens:
        _dispatch(token, stack, words)


def evaluate(input_data):
    stack = []
    words = {}
    tokens = [_parse_token(token) for line in input_data for token in line.split()]

    i = 0
    while i < len(tokens):
        token = tokens[i]
        i += 1
        if token == ":":
            if i >= len(tokens):
                raise ValueError("illegal operation")
            name = tokens[i]
            i += 1
            if isinstance(name, int):
                raise ValueError("illegal operation")
            body = []
            while i < len(tokens) and tokens[i] != ";":
                body.append(tokens[i])
                i += 1
            i += 1  # skip past ";"
            # Resolve references to user words at definition time,
            # so a word captures the definitions that exist now.
            resolved = []
            for body_token in body:
                if isinstance(body_token, str) and body_token in words:
                    resolved.extend(words[body_token])
                else:
                    resolved.append(body_token)
            words[name] = resolved
        else:
            _dispatch(token, stack, words)

    return stack

